  /// Resolves an icon by name.
  ///
  /// Names starting with `m` look up Material icons.
  /// Names starting with `c` look up Cupertino icons.
  static IconData? resolve(String name) {
    return materialIcons[name] ?? cupertinoIcons[name];
  }

  /// Whether an icon with [name] exists.
  static bool exists(String name) {
    return materialIcons.containsKey(name) || cupertinoIcons.containsKey(name);
  }
}
